from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/form-file")
async def form_file(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/file-form")
async def file_form(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_form_file():
    response = client.post(
        "/form-file",
        data={"form_data": "hello"},
        files={"file": ("test.txt", b"content")}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file": "test.txt"}

def test_file_form():
    response = client.post(
        "/file-form",
        data={"form_data": "hello"},
        files={"file": ("test.txt", b"content")}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file": "test.txt"}

if __name__ == "__main__":
    try:
        test_form_file()
        print("test_form_file passed")
    except Exception as e:
        print(f"test_form_file failed: {e}")

    try:
        test_file_form()
        print("test_file_form passed")
    except Exception as e:
        print(f"test_file_form failed: {e}")

