from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/upload")
async def upload(name: str = Form(...), file_bytes: bytes = File(...)):
    return {"name": name, "file_bytes": file_bytes}

client = TestClient(app)

def test_form_then_file_bytes():
    # This should work, but we suspect it fails with 422
    response = client.post(
        "/upload",
        data={"name": "test"},
        files={"file_bytes": b"hello world"}
    )
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

